/**
 * LUM-1070 — record ids generated by Better Auth.
 *
 * Users get a `user_` prefix so a Better Auth user id has the same shape as a
 * Clerk one (imported Clerk users keep their original `user_…` id, RFC
 * LUM-1069 §1.4). Code that recognises a raw user id by that prefix — e.g.
 * the audit-log actor filter (lib/services/audit-query.service.ts) — then
 * works the same for new and imported users. Every other model keeps Better
 * Auth's default random id.
 */
import { generateRandomString } from 'better-auth/crypto'

export const USER_ID_PREFIX = 'user_'

/** Length of the random part; Better Auth's default id length. */
const RANDOM_ID_LENGTH = 32

function randomId(): string {
  return generateRandomString(RANDOM_ID_LENGTH, 'a-z', 'A-Z', '0-9')
}

/**
 * `advanced.database.generateId`. Better Auth passes its logical model name
 * (`user`, not the Prisma model `authUser`).
 */
export function generateAuthId({ model }: { model: string }): string {
  return model === 'user' ? `${USER_ID_PREFIX}${randomId()}` : randomId()
}
